mkdir -p entrypoints/welcome && cat > entrypoints/welcome/index.html <<'EOF'
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Welcome - Chrome MCP Server</title>
  </head>
  <body>
    <div id="app"></div>
    <script type="module" src="./main.ts"></script>
  </body>
</html>
EOF
cat > entrypoints/welcome/main.ts <<'EOF'
import { createApp } from 'vue';
import App from './App.vue';

createApp(App).mount('#app');
EOF
cat > entrypoints/welcome/App.vue <<'EOF'
<template>
  <div class="page">
    <header class="header">
      <div class="brand">
        <div class="logo">
          <svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z" />
          </svg>
        </div>
        <div>
          <h1>Chrome MCP Server</h1>
          <p class="muted">After the extension is installed, this is the only required step.</p>
        </div>
      </div>
      <a class="docs-btn" :href="TROUBLESHOOTING_URL" target="_blank" rel="noopener">Troubleshooting Docs</a>
    </header>

    <main class="main">
      <section class="card">
        <h2>Install <code class="title-code">{{ PACKAGE }}</code></h2>
        <p class="muted">The Chrome extension uses this local bridge to expose MCP tools to your client.</p>

        <div class="cmd primary">
          <code>{{ installCmds.npm }}</code>
          <button @click="copy('npm', installCmds.npm)">{{ label('npm') }}</button>
        </div>

        <div class="cmd-grid">
          <div class="cmd alt">
            <div>
              <div class="cmd-tag">PNPM</div>
              <code>{{ installCmds.pnpm }}</code>
            </div>
            <button @click="copy('pnpm', installCmds.pnpm)">{{ label('pnpm') }}</button>
          </div>
          <div class="cmd alt">
            <div>
              <div class="cmd-tag">YARN</div>
              <code>{{ installCmds.yarn }}</code>
            </div>
            <button @click="copy('yarn', installCmds.yarn)">{{ label('yarn') }}</button>
          </div>
        </div>

        <p class="muted step">Then register the native host with Chrome:</p>
        <div class="cmd primary">
          <code>{{ registerCmd }}</code>
          <button @click="copy('register', registerCmd)">{{ label('register') }}</button>
        </div>

        <div class="note">Requires Node.js 18.19+. Check your version with <code class="inline">node -v</code>.</div>

        <hr />

        <h3>MCP client URL (streamable HTTP)</h3>
        <p class="muted">Use this URL in your MCP client (e.g., Claude Desktop, Claude Code, CherryStudio).</p>
        <div class="cmd primary">
          <code>{{ mcpUrl }}</code>
          <button @click="copy('url', mcpUrl)">{{ label('url') }}</button>
        </div>
        <p class="tip">Tip: You can also open the extension popup and click "Connect" to copy a full client config snippet.</p>
      </section>

      <section class="card trouble">
        <div>
          <h3>Troubleshooting</h3>
          <p class="muted">Use this only if the bridge fails to register or connect.</p>
        </div>
        <div class="cmd primary compact">
          <code>{{ doctorCmd }}</code>
          <button @click="copy('doctor', doctorCmd)">{{ label('doctor') }}</button>
        </div>
      </section>
    </main>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';

const PACKAGE = 'mcp-chrome-bridger';
const TROUBLESHOOTING_URL =
  'https://github.com/femto/mcp-chrome/blob/master/docs/TROUBLESHOOTING.md';

const installCmds = {
  npm: `npm install -g ${PACKAGE}`,
  pnpm: `pnpm add -g ${PACKAGE}`,
  yarn: `yarn global add ${PACKAGE}`,
};
