const { chromium } = require('playwright');
const path = '/Users/femtozheng/web-project/mcp-chrome/app/chrome-extension/.output/chrome-mv3';

(async () => {
  const ctx = await chromium.launchPersistentContext(__dirname + '/profile-' + Date.now(), {
    headless: false,
    channel: 'chromium',
    args: [`--disable-extensions-except=${path}`, `--load-extension=${path}`],
  });
  const log = (src) => (m) => console.log(`[${src}] ${m.type()}: ${m.text()}`.slice(0, 600));
  ctx.on('serviceworker', (sw) => sw.on?.('console', log('sw')));
  ctx.on('page', (p) => {
    p.on('console', log(p.url().split('/').pop()));
    p.on('pageerror', (e) => console.log(`[${p.url()}] pageerror: ${e.message}`));
  });
  let sw = ctx.serviceWorkers()[0] || (await ctx.waitForEvent('serviceworker'));
  sw.on?.('console', log('sw'));
  const id = sw.url().split('/')[2];
  console.log('ext id', id);

  // Attach CDP to discover offscreen document target
  const browser = ctx.browser();
  const page = await ctx.newPage();
  await page.goto(`chrome-extension://${id}/popup.html`);
  const r = await page.evaluate(() =>
    chrome.runtime.sendMessage({ type: 'initialize_semantic_engine' }),
  );
  console.log('init response', JSON.stringify(r));
  for (let i = 0; i < 10; i++) {
    const s = await page.evaluate(() => chrome.runtime.sendMessage({ type: 'get_model_status' }));
    console.log('status', JSON.stringify(s));
    if (s?.status?.initializationStatus === 'ready' || s?.status?.initializationStatus === 'error') break;
    await new Promise((r) => setTimeout(r, 3000));
  }
  await ctx.close();
})();

